using System;
using System.Linq;
using System.Collections.Generic;
using NUnit.Framework;
using UnityEngine;
using UnityEditor;
using SporeGobbo.Geometry;
using SporeGobbo.Geometry.Preview;
using SporeGobbo.CampLifecycle;
namespace SporeGobbo.CampCandidate.Tests
{
 public sealed class Stage56Tests
 {
  static CampSession New()=>new CampSession(AuthoredCamp.Create());
  [Test]public void DefinitionDeterministicCompleteAndFinite(){var a=AuthoredCamp.Create();Assert.That(a.Fingerprint(),Is.EqualTo(AuthoredCamp.Create().Fingerprint()));for(int y=0;y<192;y++)for(int x=0;x<192;x++){Assert.That(a.TrySolid(x,y,out bool solid));Assert.That(Enum.IsDefined(typeof(CampCell),a.Category(x,y)));}}
  [Test]public void CompleteDefinitionHasNoHiddenStressLocks(){var d=AuthoredCamp.Create();var w=new StreamingWorld(192,192,1,d);for(int y=0;y<192;y++)for(int x=0;x<192;x++)Assert.That(w.Locked(x,y),Is.EqualTo(d.Protected(x,y)));}
  [Test]public void CoordinateAdapterRoundTripsCellCentersAtProductionScale(){var t=new LogicalGridTransform(new Point2(-30,-18),.6,80);for(int y=0;y<80;y+=7)for(int x=0;x<128;x+=11){var p=new Point2(x+.5,y+.5);var q=t.ToLogical(t.ToWorld(p));Assert.That(q.X,Is.EqualTo(p.X).Within(1e-10));Assert.That(q.Y,Is.EqualTo(p.Y).Within(1e-10));}}
  [Test]public void StationIdsUniqueAndInteractionFootprintsFitEveryActiveState(){var s=New();Assert.That(s.Definition.Markers.Select(m=>m.Id).Distinct().Count(),Is.EqualTo(s.Definition.Markers.Count));s.FakeReturn(2,5,2);s.BuddyDied();foreach(var m in s.Definition.Markers)if(s.Active(m.Gate))Assert.That(s.Fits(m.Interaction,3),Is.True,m.Id);}
  [TestCase(1)][TestCase(3)]public void ActiveStationsConnectToFireAfterMilestones(int size){var s=New();s.FakeReturn(2,5,2);s.BuddyDied();var fire=s.Definition.Marker("fire").Interaction;foreach(var m in s.Definition.Markers)if(s.Active(m.Gate))Assert.That(s.Route(fire,m.Interaction,size).Count,Is.GreaterThan(0),m.Id);}
  [Test]public void InitialArrivalAndDepartureReachFire(){var s=New();var f=s.Definition.Marker("fire").Interaction;foreach(string id in new[]{"arrival.first","run.departure","storage"})Assert.That(s.Route(f,s.Definition.Marker(id).Interaction,3).Count,Is.GreaterThan(0),id);}
  [Test]public void ProgressionDoesNotStartEverythingUnlocked(){var s=New();Assert.That(s.FirstBuddy||s.FirstDeath||s.ShopInspected||s.FightInspected,Is.False);Assert.That(s.Active(CampCell.Shop),Is.False);s.AddBuddy();Assert.That(s.FirstBuddy);Assert.That(s.FirstDeath,Is.False);s.BuddyDied();Assert.That(s.FirstDeath);Assert.That(s.FirstBuddy,"Durable death/home facts preserve first-Buddy milestone");}
  [Test]public void BedroomCellsAreOwnedAndPlayerCannotExcavateThem(){var s=New();var cells=s.Definition.Bedrooms.SelectMany(r=>r.Cells).ToArray();Assert.That(cells.Length,Is.GreaterThan(0));Assert.That(s.DigPlayer(cells),Is.Zero);Assert.That(s.Established,Is.Zero);}
  [Test]public void BedFootprintsAndFireRoutesFitAfterTenSequentialConstructions(){var s=New();for(int i=0;i<10;i++){s.AddBuddy();Assert.That(s.ConstructNext(out string why),Is.True,$"bed{i+1}: {why}");Assert.That(s.Established,Is.EqualTo(i+1));var r=s.Definition.RoomForSlot(i+1);var bed=r.Beds[i+1-r.FirstSlot];Assert.That(s.Fits(bed,3));Assert.That(s.Route(bed,s.Definition.Marker("fire").Interaction,3).Count,Is.GreaterThan(0));}Assert.That(s.ConstructNext(out _),Is.False);}
  [Test]public void SharedBedroomPreservesUniqueBedOwnership(){var s=New();for(int i=0;i<3;i++){s.AddBuddy();Assert.That(s.ConstructNext(out _));}Assert.That(s.Residents.Select(r=>r.Slot).Distinct().Count(),Is.EqualTo(3));Assert.That(s.Definition.RoomForSlot(1),Is.SameAs(s.Definition.RoomForSlot(3)));}
  [Test]public void DeathVacancyClaimedBeforeAdditionalExcavation(){var s=New();s.AddBuddy();Assert.That(s.ConstructNext(out _));s.BuddyDied();s.AddBuddy();Assert.That(s.Residents.Last().Slot,Is.EqualTo(1));Assert.That(s.Established,Is.EqualTo(1));Assert.That(s.ConstructNext(out _),Is.False);}
  [Test]public void FakeReturnValidatesBeforeStateMutation(){var s=New();Assert.Throws<ArgumentException>(()=>s.FakeReturn(-1,5,2));Assert.That(s.Returns,Is.Zero);s.FakeReturn(2,5,2);Assert.That(s.Living,Is.EqualTo(2));Assert.That(s.Mushrooms,Is.EqualTo(5));Assert.That(s.Shinies,Is.EqualTo(2));Assert.That(s.Discovered);}
  [Test]public void ShopReservationPrecedesFightPitAndOpensInspectionRoutes(){var s=New();s.FakeReturn(2,5,2);s.ConstructNext(out _);s.ConstructNext(out _);s.BuddyDied();s.Advance();Assert.That(s.ShopInspected);Assert.That(s.FightInspected,Is.False);Assert.That(s.Route(s.Definition.Marker("fire").Interaction,s.Definition.Marker("shop.reserved").Interaction,3).Count,Is.GreaterThan(0));s.Advance();Assert.That(s.FightInspected);Assert.That(s.Route(s.Definition.Marker("fire").Interaction,s.Definition.Marker("fight.reserved").Interaction,3).Count,Is.GreaterThan(0));}
  [Test]public void LandmarkFootprintsStayPermanentAndDistinctFromSilhouette(){var s=New();Assert.That(s.Definition.Landmarks.Count,Is.GreaterThan(0));foreach(var l in s.Definition.Landmarks){Assert.That(l.MaterialId,Is.Not.Empty);foreach(var c in l.ProtectedCells)Assert.That(s.Definition.Protected(c.X,c.Y));Assert.That(l.SilhouetteBounds.Max.X,Is.GreaterThan(l.SilhouetteBounds.Min.X));}}
  [Test]public void NoFabricatedDeathWithoutLivingBuddy(){var s=New();Assert.That(s.BuddyDied(),Is.False);Assert.That(s.Deaths,Is.Zero);}
  [Test]public void SessionMutationsPublishUniqueAcceptedBatches(){var s=New();var batches=new List<CampBatch>();s.Committed+=batches.Add;var cells=new List<DualTile>();for(int y=0;y<192;y++)for(int x=0;x<192;x++)if(s.Definition.Category(x,y)==CampCell.Expansion)cells.Add(new DualTile(x,y));int n=s.DigPlayer(cells.Concat(cells));Assert.That(n,Is.EqualTo(cells.Count));Assert.That(batches.Count,Is.EqualTo(1));Assert.That(batches[0].Cells.Count,Is.EqualTo(n));Assert.That(s.Revision,Is.EqualTo(1));Assert.That(s.DigPlayer(cells),Is.Zero);}
  [Test]public void PermanentCellsPreservedAcrossAllGrowth(){var s=New();s.FakeReturn(8,10,5);for(int i=0;i<8;i++)s.ConstructNext(out _);s.BuddyDied();for(int y=0;y<192;y++)for(int x=0;x<192;x++)if(s.Definition.Protected(x,y))Assert.That(s.Terrain.IsSolid(x,y));}
  [Test]public void SweptMovementCannotSkipThinPermanentBoundary(){var s=New();var p=s.Definition.Marker("arrival.first").Interaction;var q=s.Move(p,new Point2(0,100),1);Assert.That(s.Fits(q,1));Assert.That(q.Y,Is.LessThan(165));}
  [Test]public void IncrementalGeometryEqualsFreshAfterAcceptedExpansionBatch(){var s=New();var w=s.BindReadOnlyGeometry();using(var stream=new StreamingGeometry(w,384,true)){var map=new FocusProjection(new Point2(88,92),52,28,30,.55,.12,1.9,new Point2(0,5));stream.Select(map,87,49,2.15);for(int i=0;i<1000&&!stream.Ready;i++)stream.Pump(99,1000);s.Committed+=b=>stream.RefreshPhysicalCells(b.Cells);s.DigPlayer(new[]{new DualTile(76,108),new DualTile(77,108)});foreach(var c in stream.Resident.Values){var fresh=PreviewMeshBuilder.BuildOptimizedRows(new ChunkReadWindow(w,c.Key),new ContourTerrainCache(new ChunkReadWindow(w,c.Key)),c.Key.X*16,c.Key.Y*16,16,0,16,null,new PreviewMeshWorkspace(),true,true);for(int l=0;l<4;l++){Assert.That(c.Layers[l].Indices,Is.EqualTo(fresh[l].Indices));Assert.That(c.Layers[l].Vertices,Is.EqualTo(fresh[l].Vertices));}}}}
  [Test]public void GeometryBindingCannotBypassMutationOwner(){var s=New();Assert.Throws<InvalidOperationException>(()=>s.BindReadOnlyGeometry().Excavate(76,108));Assert.Throws<InvalidOperationException>(()=>s.BindReadOnlyGeometry().TakeExcavationControl());Assert.That(s.Revision,Is.Zero);}
  [Test]public void PurePoliciesRemainTheActualOwnershipAndCommitRules(){Assert.That(CampArrivalPolicy.CanBeginReservedConstruction(2,1,1));Assert.That(CampSpatialPolicy.CanCommitResidentialConstruction(2,1,0),Is.False);Assert.That(CampSpatialPolicy.CanCommitResidentialConstruction(2,2,0));}
  [Test]public void BedroomIsNotEstablishedUntilLiveConstructionFinishes(){var s=New();s.AddBuddy();Assert.That(s.BeginConstruction(out _));Assert.That(s.Established,Is.Zero);Assert.That(s.Construction,Is.Not.Null);for(int i=0;i<20000&&s.Construction!=null;i++)s.TickConstruction(.05);Assert.That(s.Established,Is.EqualTo(1));}
  [Test]public void ResetCanDiscardAnInProgressConstructionWithoutTouchingTheNewWorld(){var old=New();old.AddBuddy();old.BeginConstruction(out _);old.TickConstruction(.1);var fresh=New();Assert.That(fresh.Construction,Is.Null);Assert.That(fresh.Established+fresh.Revision+fresh.Living,Is.Zero);}
  [Test]public void OldControllersAreNotPresentInCandidateScene(){string yaml=System.IO.File.ReadAllText("Assets/Terrain/Camp/Scenes/FutureCampStage56.unity");foreach(string name in new[]{"Stage50Preview","Stage55Preview"}){string guid=AssetDatabase.AssetPathToGUID("Assets/Terrain/Geometry/Preview/Runtime/"+name+".cs");Assert.That(yaml.Contains("guid: "+guid+","),Is.False,name);}}
  [Test]public void RepeatedSessionResetProducesSameInitialState(){for(int i=0;i<8;i++){var s=New();Assert.That(s.Living+s.Established+s.Deaths+s.Returns,Is.Zero);Assert.That(s.Revision,Is.Zero);Assert.That(s.Definition.Fingerprint(),Is.EqualTo(AuthoredCamp.Create().Fingerprint()));}}
  [Test]public void CandidateSceneHasNoProductionRegistrarsOrSaveComponents(){var scene="Assets/Terrain/Camp/Scenes/FutureCampStage56.unity";Assert.That(System.IO.File.Exists(scene));string yaml=System.IO.File.ReadAllText(scene);foreach(string forbidden in new[]{"HandcraftedCampTerrain","MapGenerator","GameState","CampRunPortal","CampSceneController"}){string guid=AssetDatabase.AssetPathToGUID("Assets/"+forbidden+".cs");Assert.That(yaml.Contains("guid: "+guid+","),Is.False,forbidden);}}
  [Test]public void MemorialApproachIsIndependentOfFirstDeath(){var s=New();Assert.That(s.Active(s.Definition.Marker("bones").Gate),Is.False);Assert.That(s.Route(s.Definition.Marker("fire").Interaction,s.Definition.Marker("bones").Interaction,3).Count,Is.GreaterThan(0));for(int y=45;y<80;y++)for(int x=65;x<110;x++)Assert.That(s.Definition.Category(x,y),Is.Not.EqualTo(CampCell.FirstDeath));}
  [Test]public void BonesPortalShortcutIsOrdinaryWhileStationBackingRemainsPermanent(){var s=New();var earth=new List<DualTile>();for(int y=57;y<=64;y++)for(int x=81;x<=92;x++)if(s.Definition.Category(x,y)==CampCell.Expansion)earth.Add(new DualTile(x,y));Assert.That(earth.Count,Is.GreaterThan(8));Assert.That(s.DigPlayer(earth),Is.EqualTo(earth.Count));Assert.That(s.FirstDeath,Is.False);foreach(string id in new[]{"bones","run.departure"}){var m=s.Definition.Marker(id);for(int y=(int)m.Anchor.Y-3;y<=(int)m.Anchor.Y;y++)for(int x=(int)m.Anchor.X-3;x<=(int)m.Anchor.X+3;x++)Assert.That(s.Definition.Protected(x,y));}}
  [Test]public void EarlySharedPocketsHavePublicThreeCellApproachesBesideFire(){var s=New();foreach(var room in s.Definition.Bedrooms.Take(2)){Assert.That(room.Beds.Count,Is.EqualTo(3));Assert.That(room.Entrance.Y,Is.LessThan(s.Definition.Marker("fire").Interaction.Y));Assert.That(s.Route(s.Definition.Marker("fire").Interaction,room.Entrance,3).Count,Is.GreaterThan(0));}}
  [Test]public void CentralEarthIsInitiallySolidAndDoesNotReplaceProtectedStationsOrProgression(){var s=New();var earth=new List<DualTile>();for(int y=53;y<100;y++)for(int x=93;x<134;x++)if(s.Definition.Category(x,y)==CampCell.Expansion)earth.Add(new DualTile(x,y));Assert.That(earth.Count,Is.GreaterThan(350));Assert.That(earth.All(c=>s.Terrain.IsSolid(c.X,c.Y)));Assert.That(s.DigPlayer(earth),Is.EqualTo(earth.Count));Assert.That(s.FirstBuddy||s.FirstDeath||s.ShopInspected||s.FightInspected,Is.False);foreach(string id in new[]{"squad","run.departure","bones"}){var m=s.Definition.Marker(id);for(int y=(int)m.Anchor.Y-3;y<=(int)m.Anchor.Y;y++)for(int x=(int)m.Anchor.X-3;x<=(int)m.Anchor.X+3;x++)Assert.That(s.Terrain.IsSolid(x,y)&&s.Definition.Protected(x,y),Is.True,id);}s.AddBuddy();Assert.That(s.Route(s.Definition.Marker("fire").Interaction,s.Definition.Marker("squad").Interaction,3).Count,Is.GreaterThan(0));}
  [Test]public void OptionalCentralExcavationCreatesComfortableShortcutWithoutUnlockingFacilities(){var s=New();s.AddBuddy();var a=s.Definition.Marker("squad").Interaction;var b=s.Definition.Marker("run.departure").Interaction;int before=s.Route(a,b,3).Count;var cells=new List<DualTile>();for(int y=53;y<100;y++)for(int x=93;x<134;x++)if(s.Definition.Category(x,y)==CampCell.Expansion)cells.Add(new DualTile(x,y));s.DigPlayer(cells);int after=s.Route(a,b,3).Count;Assert.That(after,Is.GreaterThan(0));Assert.That(after,Is.LessThan(before));Assert.That(s.Active(CampCell.Shop)||s.Active(CampCell.FightPit),Is.False);}
  [Test]public void RealRecoveryAndSnackServicesRemainIntegrationGap(){Assert.Ignore("Integration gap: candidate does not call GameState/live healing/snacks or save services");}
  [Test]public void RealRosterSuccessionAndCampaignSlotsRemainIntegrationGap(){Assert.Ignore("Integration gap: real roster, death succession, campaign save and scene routes intentionally unconnected");}
  [Test]public void ProductionBuddyPhysicsAndResidentialCoroutineRemainIntegrationGap(){Assert.Ignore("Integration gap: pure policies are reused; real BuddyDigAbility/Rigidbody construction coroutine is not connected");}
 }
}
